function validate([word]) {
  if (typeof word !== 'string' || word.length < 1 || word.length > 200000) return 'word needs 1 to 200000 characters.';
  if (!/^[a-z]+$/.test(word)) return 'word may contain only lowercase English letters.';
  return null;
}

