function maxSubstrings(word) {
  const firstSeen = new Map();
  let count = 0;
  for (let i = 0; i < word.length; i++) {
    const letter = word[i];
    if (!firstSeen.has(letter)) {
      firstSeen.set(letter, i);
    } else if (i - firstSeen.get(letter) >= 3) {
      count++;
      firstSeen.clear();
    }
  }
  return count;
}

