function maxSubstrings(word) {
  // best[end]: the most pieces that fit inside word[0..end-1]; try every piece that ends at end - 1.
  const n = word.length;
  const best = new Array(n + 1).fill(0);
  for (let end = 1; end <= n; end++) {
    best[end] = best[end - 1];
    for (let start = 0; start + 4 <= end; start++) {
      if (word[start] === word[end - 1]) best[end] = Math.max(best[end], best[start] + 1);
    }
  }
  return best[n];
}

