function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  // A small alphabet makes repeated letters, and so pieces, common.
  const alphabet = size === 'large' ? 2 + Math.floor(rand() * 25) : 1 + Math.floor(rand() * 5);
  const n = size === 'large' ? 10000 - Math.floor(rand() * 1000) : 1 + Math.floor(rand() * 16);
  let word = '';
  for (let i = 0; i < n; i++) word += letters[Math.floor(rand() * alphabet)];
  return [word];
}
